  const amber = a.health_score === 3 || (a.interactions_count >= 1 && a.interactions_count <= 2) || (contactAge >= 14 && contactAge < 30) || a.open_issue_count > 0 || renewalDays <= 60 || a.delivery_status === 'at_risk';
